// Monta um Adaptive Card do Teams para o evento recebido do QA Hub.
const e = $input.first().json.body ?? $input.first().json;
const run = e.run ?? {};
const pct = (v) => (v === null || v === undefined ? '—' : `${String(v).replace('.', ',')}%`);
const head = `${run.plan ?? ''} · build ${run.build ?? ''}`;
let body = [];

if (e.type === 'run_concluido') {
  const t = e.totals ?? {};
  const ok = !t.failed && !t.blocked;
  body = [
    { type: 'TextBlock', text: ok ? '✅ Run concluído' : '⚠️ Run concluído com falhas', weight: 'Bolder', size: 'Medium', wrap: true },
    { type: 'TextBlock', text: run.title ?? '', wrap: true },
    { type: 'TextBlock', text: head, isSubtle: true, spacing: 'None', wrap: true },
    { type: 'FactSet', facts: [
      { title: 'Sucesso', value: pct(e.passRate) },
      { title: 'Passou', value: String(t.passed ?? 0) },
      { title: 'Falhou', value: String(t.failed ?? 0) },
      { title: 'Bloqueado', value: String(t.blocked ?? 0) },
      { title: 'Total', value: String(t.total ?? 0) },
    ] },
  ];
} else if (e.type === 'diagnostico_pronto') {
  body = [
    { type: 'TextBlock', text: '🔎 Diagnóstico da IA pronto', weight: 'Bolder', size: 'Medium', wrap: true },
    { type: 'TextBlock', text: run.title ?? '', wrap: true },
    { type: 'TextBlock', text: head, isSubtle: true, spacing: 'None', wrap: true },
    ...(e.summary ? [{ type: 'TextBlock', text: e.summary, wrap: true }] : []),
    ...(e.causes ?? []).map((c, i) => ({
      type: 'TextBlock',
      wrap: true,
      text: `**${i + 1}. ${c.title}** (${c.cases} ${c.cases === 1 ? 'caso' : 'casos'})\n\n${c.action ?? ''}`,
    })),
  ];
} else {
  throw new Error('Evento desconhecido: ' + e.type);
}

const card = {
  $schema: 'http://adaptivecards.io/schemas/adaptive-card.json',
  type: 'AdaptiveCard',
  version: '1.4',
  msteams: { width: 'Full' },
  body,
  ...(e.link ? { actions: [{ type: 'Action.OpenUrl', title: 'Abrir no QA Hub', url: e.link }] } : {}),
};
return [{ json: { type: 'message', attachments: [{ contentType: 'application/vnd.microsoft.card.adaptive', contentUrl: null, content: card }] } }];
